"""Standalone, offline HTML: frozen probabilities and supplied 90-minute results."""
from pathlib import Path
import sys
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
sys.path[:0]=[str(ROOT/'src'),str(ROOT/'.deps'),str(ROOT/'tools'),str(ROOT)]
from verify_final_evaluation import frozen_checks,protocol_checks
from run_final_evaluation import check_prediction_commit
from football_forecast.final_evaluation import MODEL_NAMES,PROBABILITY_COLUMNS
frozen_checks();protocol_checks(True);check_prediction_commit()
folder=ROOT/'reports/final_evaluation'
frames={name:pd.read_csv(folder/f'worldcup_group_scored_{name}.csv') for name in MODEL_NAMES}
forecast=pd.read_csv(folder/'group_forecasts_logistic.csv')
scores=pd.read_csv(folder/'group_score_matrix_poisson.csv')
top={str(k):g.nlargest(5,'probability')[['home_goals','away_goals','probability']].to_dict('records') for k,g in scores.groupby('match_id')}
fixtures=[]
for r in forecast.itertuples(index=False):
    row=frames['logistic'][frames['logistic'].match_id.eq(r.match_id)].iloc[0]
    fixture={'id':r.match_id,'group':r.group,'date':r.date[:10],'a':r.home_team,'b':r.away_team,
             'score':f'{int(row.x12_home_score)}–{int(row.x12_away_score)}','outcome':int(row.x12_target),
             'topScores':top[str(r.match_id)],'models':{}}
    for name,frame in frames.items():
        point=frame[frame.match_id.eq(r.match_id)].iloc[0]
        fixture['models'][name]={'p':[float(point[c]) for c in PROBABILITY_COLUMNS],
                                'loss':float(point.log_loss),'brier':float(point.brier)}
        if name=='poisson':fixture['rates']=[float(point.lambda_home),float(point.lambda_away)]
    fixtures.append(fixture)
semi=pd.read_csv(folder/'semiconfirmatory_metrics.csv')
world=pd.read_csv(folder/'worldcup_group_metrics.csv')
selection=pd.read_csv(ROOT/'reports/models_selected/model_comparison.csv')
def metrics(frame,scope=None):
    if scope:frame=frame[frame[scope[0]].eq(scope[1])]
    return [{'id':r.model,'name':MODEL_NAMES[r.model],'n':int(r.matches),'ll':float(r.log_loss),
             'brier':float(r.brier),'accuracy':float(r.accuracy),'draw':float(r.p_draw if hasattr(r,'p_draw') else r.predicted_draw_rate),
             'actualDraw':float(r.actual_draw if hasattr(r,'actual_draw') else r.actual_draw_rate)} for r in frame.itertuples()]
data={'fixtures':fixtures,'modelNames':MODEL_NAMES,
      'metrics':{'selection':metrics(selection,('scope','non_friendlies')),
                 'semi':metrics(semi,('stratum','non_friendlies')),'world':metrics(world)},
      'semiConclusion':json.loads((folder/'semiconfirmatory_conclusion.json').read_text(encoding='utf-8')),
      'worldConclusion':json.loads((folder/'worldcup_conclusion.json').read_text(encoding='utf-8'))}
html=r'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Probabilidades de fútbol internacional</title>
<style>
:root{--ink:#173047;--muted:#5e7385;--border:#dbe4ec;--paper:#fff;--bg:#f3f6fa;--green:#087f6c;--blue:#557ca3;--gold:#bc8530}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}
header{background:#142d43;color:#fff;padding:30px max(24px,calc((100vw - 1240px)/2)) 40px}header small{letter-spacing:2px;color:#9cc7cc;font-weight:700;text-transform:uppercase}h1{font-size:clamp(28px,4vw,44px);line-height:1.12;max-width:850px;margin:14px 0}header p{max-width:800px;color:#cad8e4;margin:12px 0 0}.tag{display:inline-block;border:1px solid #496074;border-radius:30px;padding:4px 12px;margin-top:16px;font-size:12px}
main{max-width:1240px;margin:0 auto;padding:24px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:-46px 0 26px}.card,.panel{background:var(--paper);border:1px solid var(--border);border-radius:14px;padding:20px;box-shadow:0 5px 18px #17304707}.card small{display:block;color:var(--muted)}.card strong{display:block;font-size:28px;margin:5px 0}.card span{font-size:12px;color:var(--muted)}h2{font-size:23px;margin:0 0 7px}h3{font-size:18px;margin:0 0 10px}.muted{color:var(--muted)}.panel{margin-bottom:22px}.bar{height:9px;display:flex;border-radius:8px;overflow:hidden;background:#eaf0f5}.bar>i{display:block;height:100%}.a{background:var(--green)}.draw{background:var(--gold)}.b{background:var(--blue)}
.filters{display:grid;grid-template-columns:2fr 1fr 1.7fr 1fr;gap:12px;margin:20px 0 16px}label{display:block;font-size:12px;font-weight:650;color:var(--muted)}input,select{width:100%;margin-top:5px;border:1px solid var(--border);border-radius:8px;background:#fff;color:var(--ink);padding:10px;font:inherit}input:focus,select:focus{outline:2px solid #95d3c9;outline-offset:1px}.split{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(290px,1fr);gap:20px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.45px;text-align:left;padding:11px 10px;border-bottom:1px solid var(--border);white-space:nowrap}td{padding:13px 10px;border-bottom:1px solid #edf2f6}tbody tr.match{cursor:pointer}tbody tr.match:hover,tbody tr.active{background:#eef8f5}.num{text-align:right;font-variant-numeric:tabular-nums}.teams{min-width:165px;font-weight:600}.vs{font-weight:400;color:var(--muted);font-size:12px}.result{display:inline-block;background:#eef3f7;border-radius:6px;padding:3px 9px;font-weight:700;white-space:nowrap}.prob{min-width:135px}.probtext{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:5px}.help{background:#eff6fb;border-left:3px solid var(--blue);padding:12px 14px;margin-top:15px;border-radius:4px;color:#425d73;font-size:13px}.notice{padding:12px 16px;background:#fff8e9;border:1px solid #e9d8b7;border-radius:9px;font-size:13px;color:#6c552a}.detail{position:sticky;top:18px;align-self:start}.detail .title{font-size:23px;line-height:1.25;font-weight:750;margin-bottom:8px}.detail .subtitle{color:var(--muted);font-size:12px}.detail .section{border-top:1px solid var(--border);margin-top:18px;padding-top:17px}.pr{display:grid;grid-template-columns:1fr auto;gap:6px;margin:12px 0}.pr strong{font-variant-numeric:tabular-nums}.minibar{height:6px;background:#edf2f5;border-radius:6px;grid-column:1/-1;overflow:hidden}.minibar i{display:block;height:100%;background:var(--green)}.scores{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}.score{border:1px solid var(--border);border-radius:8px;text-align:center;padding:9px 4px}.score strong{display:block}.score small{color:var(--muted);font-size:10px}.legend{display:flex;gap:18px;font-size:12px;color:var(--muted);margin-top:10px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}button{font:inherit;color:var(--ink);border:1px solid var(--border);border-radius:8px;background:#fff;padding:8px 12px;cursor:pointer}button:hover{background:#eff6fb}.small{font-size:12px}.footer{color:var(--muted);font-size:12px;padding:10px 2px 25px}.badge{background:#e4f4ef;color:#126552;border-radius:5px;padding:3px 7px;font-size:11px}.wide td{font-size:13px}.metrics-controls{display:flex;gap:10px;margin:15px 0}details>summary{cursor:pointer;font-weight:650}details p{color:var(--muted);max-width:920px}.metric-chart{margin:20px 0}.metric-row{display:grid;grid-template-columns:220px 1fr 65px;gap:12px;align-items:center;margin:12px 0;font-size:13px}.metric-track{background:#edf2f6;border-radius:5px;height:11px;overflow:hidden}.metric-track i{display:block;background:var(--blue);height:100%}
@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}.detail{position:static}.filters{grid-template-columns:1fr 1fr}.metric-row{grid-template-columns:170px 1fr 60px}}@media(max-width:560px){main{padding:16px}.filters{grid-template-columns:1fr}.cards{gap:10px}.card{padding:14px}.card strong{font-size:23px}.scores{gap:4px}.legend{gap:10px}.panel{padding:15px}.metric-row{grid-template-columns:140px 1fr 55px}}
</style></head><body>
<header><small>Estudio retrospectivo · fútbol de selecciones</small><h1>72 encuentros.<br>Probabilidades que puedo comprobar.</h1><p>Estimo victoria, empate y derrota, exploro marcadores y contrasto con resultados registrados a 90 minutos. Distingo la evidencia de selección, la evaluación semiconfirmatoria y la descripción del Mundial.</p><span class="tag">Corte deportivo: 9 de junio de 2026 · modelos sin reajuste desde 2022</span></header>
<main><div class="cards"><div class="card"><small>Partidos de grupos</small><strong>72</strong><span>48 selecciones · resultados a 90 minutos</span></div><div class="card"><small>Referencia principal</small><strong>Solo Elo</strong><span>Con ventaja de sede fija</span></div><div class="card"><small>Producto 1X2 seleccionado</small><strong>Logística</strong><span>Elo y forma · sin cambiar coeficientes</span></div><div class="card"><small>Producto de marcadores</small><strong>Poisson</strong><span>Distribución propia · sin reconciliación</span></div></div>
<section class="panel"><h2>Exploro cada partido</h2><p class="muted">Cambio el método, filtro una selección y selecciono un encuentro para ver sus probabilidades y los marcadores Poisson más probables.</p><div class="filters"><label>Selección o partido<input id="search" placeholder="Ejemplo: Colombia" aria-label="Buscar selección"></label><label>Grupo<select id="group"><option value="">Todos los grupos</option></select></label><label>Método 1X2<select id="method"></select></label><label>Orden<select id="sort"><option value="date">Fecha y grupo</option><option value="error">Mayor error del método</option><option value="draw">Mayor probabilidad de empate</option></select></label></div><div class="split"><div><div class="scroll"><table><thead><tr><th>Grupo / fecha UTC</th><th>Partido</th><th>Probabilidades A · empate · B</th><th>Resultado registrado</th></tr></thead><tbody id="matches"></tbody></table></div><div class="legend"><span><i class="dot a"></i>Victoria A</span><span><i class="dot draw"></i>Empate</span><span><i class="dot b"></i>Victoria B</span></div><p id="count" class="small muted"></p><button id="export">Exportar selección como CSV</button></div><aside id="detail" class="detail"></aside></div></section>
<section class="panel"><h2>Comparo la evidencia</h2><p class="muted">Menor log loss y Brier son mejores. La comparación principal usa no amistosos. Los grupos del Mundial son una muestra pequeña y descriptiva.</p><div class="metrics-controls"><label>Ventana de evaluación<select id="window"><option value="semi">2023–corte · semiconfirmatoria</option><option value="selection">2016–2022 · selección</option><option value="world">Mundial · 72 grupos descriptivos</option></select></label></div><div id="comparisonChart" class="metric-chart"></div><div class="scroll"><table class="wide"><thead><tr><th>Método</th><th class="num">N</th><th class="num">Log loss</th><th class="num">Brier</th><th class="num">Acierto</th><th class="num">Empate previsto</th><th class="num">Empate real</th></tr></thead><tbody id="comparison"></tbody></table></div><div class="help">En 2023–corte, la diferencia de log loss de logística frente a Elo es <strong id="delta"></strong>, con IC trimestral <strong id="interval"></strong>. Mejora en los cuatro subperiodos. En los 72 grupos, el intervalo frente a Elo incluye cero: no declaro superioridad.</div></section>
<section class="panel"><details><summary>Cómo interpreto los datos y los límites</summary><p>El estudio se construyó con el torneo ya jugado. La entrega histórica DataCamp había evaluado 846 partidos de 2023–2026; la excluyo de comparaciones y considero el periodo semiconfirmatorio. Las predicciones de grupos se sellaron antes de cargar resultados del Mundial.</p><p>Actualizo Elo y forma solo con resultados anteriores a cada partido. Donde no verifico 90 minutos, uso el marcador final como aproximación marcada. Una tanda no implica empate a 90 minutos. Logística y Poisson son modelos distintos: muestro cada 1X2 y los marcadores Poisson sin forzar coincidencia.</p><p>Para inferencia exijo 200 partidos y 30 eventos por clase. Uso 2.000 remuestreos por trimestre y sensibilidad mensual; reporto clústeres reales. Los 72 grupos y las eliminatorias son descriptivos. La evaluación de eliminatorias condiciona participantes conocidos retrospectivamente.</p><p>Las fuentes suministradas coinciden en los 72 marcadores de grupos; 24 fechas difieren por convención local/UTC. Registro además el solapamiento operativo de 10,312 segundos entre inicio de carga oficial y cierre del remuestreo semiconfirmatorio, con modelos y pronósticos ya congelados y entradas separadas.</p></details></section>
<p class="footer">Probabilidades de fútbol internacional · datos locales suministrados · resultado registrado, no certeza de pronóstico · funcionamiento sin conexión</p></main>
<script>const DATA=__DATA__;
const names={"United States":"Estados Unidos","Korea Republic":"Corea del Sur","IR Iran":"Irán","Ivory Coast":"Costa de Marfil","Curacao":"Curazao","DR Congo":"RD Congo","Turkey":"Turquía","Czech Republic":"Chequia","Bosnia-Herzegovina":"Bosnia y Herzegovina","South Africa":"Sudáfrica","Saudi Arabia":"Arabia Saudita","New Zealand":"Nueva Zelanda","England":"Inglaterra","Scotland":"Escocia","Germany":"Alemania","Netherlands":"Países Bajos","France":"Francia","Spain":"España","Sweden":"Suecia","Switzerland":"Suiza","Morocco":"Marruecos","Algeria":"Argelia","Egypt":"Egipto","Japan":"Japón","Brazil":"Brasil","Ghana":"Ghana","Canada":"Canadá","Mexico":"México","Qatar":"Catar","Haiti":"Haití","Iraq":"Irak","Jordan":"Jordania","Norway":"Noruega","Croatia":"Croacia","Tunisia":"Túnez","Belgium":"Bélgica","Austria":"Austria","Uzbekistan":"Uzbekistán"};
const t=n=>names[n]||n;const $=id=>document.getElementById(id);const pct=n=>(100*n).toFixed(1)+'%';const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let chosen=1,shown=[];
for(const g of 'ABCDEFGHIJKL')$('group').add(new Option('Grupo '+g,g));for(const [id,name] of Object.entries(DATA.modelNames))$('method').add(new Option(name,id));$('method').value='logistic';
function render(){const term=$('search').value.toLowerCase(),g=$('group').value,m=$('method').value;shown=DATA.fixtures.filter(f=>(!g||f.group===g)&&(`${t(f.a)} ${t(f.b)} ${f.a} ${f.b}`.toLowerCase().includes(term)));shown.sort((a,b)=>$('sort').value==='error'?b.models[m].loss-a.models[m].loss:$('sort').value==='draw'?b.models[m].p[1]-a.models[m].p[1]:a.date.localeCompare(b.date)||a.id-b.id);if(!shown.some(f=>f.id===chosen)&&shown.length)chosen=shown[0].id;$('matches').innerHTML=shown.map(f=>{const p=f.models[m].p;return `<tr class="match ${f.id===chosen?'active':''}" data-id="${f.id}"><td><span class="badge">${f.group}</span><br><small class="muted">${f.date}</small></td><td class="teams">${safe(t(f.a))}<br><span class="vs">vs</span> ${safe(t(f.b))}</td><td class="prob"><div class="probtext"><span>${pct(p[0])}</span><span>${pct(p[1])}</span><span>${pct(p[2])}</span></div><div class="bar"><i class="a" style="width:${p[0]*100}%"></i><i class="draw" style="width:${p[1]*100}%"></i><i class="b" style="width:${p[2]*100}%"></i></div></td><td><span class="result">${f.score}</span></td></tr>`}).join('');$('count').textContent=shown.length+' de 72 encuentros';for(const row of $('matches').querySelectorAll('tr'))row.onclick=()=>{chosen=Number(row.dataset.id);render()};detail()}
function detail(){const f=shown.find(f=>f.id===chosen);if(!f){$('detail').innerHTML='<p class="muted">No hay partidos para ese filtro.</p>';return}const m=$('method').value,p=f.models[m].p,pp=f.models.poisson.p;const labels=[t(f.a)+' gana','Empate',t(f.b)+' gana'];$('detail').innerHTML=`<div class="title">${safe(t(f.a))}<br><span class="muted">vs</span> ${safe(t(f.b))}</div><div class="subtitle">Grupo ${f.group} · ${f.date} UTC</div><div class="section"><h3>${safe(DATA.modelNames[m])}</h3>${p.map((v,i)=>`<div class="pr"><span>${safe(labels[i])}</span><strong>${pct(v)}</strong><div class="minibar"><i style="width:${100*v}%"></i></div></div>`).join('')}<p class="small muted">Resultado registrado: <strong>${f.score}</strong> a 90 minutos.</p></div><div class="section"><h3>Marcadores de Poisson</h3><div class="scores">${f.topScores.map(s=>`<div class="score"><strong>${s.home_goals}–${s.away_goals}</strong><small>${pct(s.probability)}</small></div>`).join('')}</div><p class="small muted">Promedio estimado de goles: ${f.rates[0].toFixed(2)} · ${f.rates[1].toFixed(2)}.</p><p class="small">1X2 de Poisson: ${pp.map(pct).join(' · ')}</p><div class="help">Estos marcadores proceden de Poisson. Cuando selecciono logística, su 1X2 es otro producto y puede diferir.</div></div>`}
function comparison(){const rows=DATA.metrics[$('window').value];$('comparison').innerHTML=rows.map(r=>`<tr><td>${safe(r.name)}</td><td class="num">${r.n}</td><td class="num">${r.ll.toFixed(4)}</td><td class="num">${r.brier.toFixed(4)}</td><td class="num">${pct(r.accuracy)}</td><td class="num">${pct(r.draw)}</td><td class="num">${pct(r.actualDraw)}</td></tr>`).join('');const lo=Math.min(...rows.map(r=>r.ll))*.9,hi=Math.max(...rows.map(r=>r.ll));$('comparisonChart').innerHTML=rows.map(r=>`<div class="metric-row"><span>${safe(r.name)}</span><div class="metric-track"><i style="width:${(r.ll-lo)/(hi-lo)*100}%;background:${r.id==='logistic'?'var(--green)':'var(--blue)'}"></i></div><strong>${r.ll.toFixed(4)}</strong></div>`).join('')}
for(const id of ['search','group','method','sort'])$(id).addEventListener(id==='search'?'input':'change',render);$('window').onchange=comparison;$('delta').textContent=DATA.semiConclusion.primary_log_loss_difference.toFixed(5);$('interval').textContent='['+DATA.semiConclusion.primary_log_loss_difference_ci.map(x=>x.toFixed(5)).join('; ')+']';$('export').onclick=()=>{const m=$('method').value;const rows=[['grupo','fecha_utc','equipo_a','equipo_b','victoria_a','empate','victoria_b','resultado_90'],...shown.map(f=>[f.group,f.date,t(f.a),t(f.b),...f.models[m].p,f.score])];const text=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download='probabilidades_mundial.csv';a.click();URL.revokeObjectURL(a.href)};render();comparison();
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\\u003c'))
html=html.replace('.scroll{overflow:auto}', '.scroll{overflow:auto;max-height:660px}th{position:sticky;top:0;background:white;z-index:1}')
(folder/'football_report.html').write_text(html,encoding='utf-8')
print('Informe HTML sin conexión generado: 72 partidos y ocho métodos con nombres legibles.')
